def transform_final_solution(grid):
    """Solution version with cp2 only placed if empty in original"""
    height, width = len(grid), len(grid[0])
    result = [[0 for _ in range(width)] for _ in range(height)]

    row_shifts = {1: -1, 2: 0, 3: -1, 6: -1}
    col_shifts = {1: -2, 2: -4, 3: -4, 6: -4}

    orig_grid = [row[:] for row in grid]

    colored = []
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != 0:
                colored.append((r, c, val))

    for cr, cc, cval in colored:
        d_row = row_shifts.get(cval, 0)
        d_col = col_shifts.get(cval, 0)

        cp1 = (cr + d_row, cc)
        cp2 = (cr, cc + d_col)

        # Diagonal copy
        if cp1[0] >= 0 and cp1[1] >= 0:
            result[cp1[0]][cp1[1]] = cval

            r1, c1 = cp1
            dr, dc = cr - r1, cc - c1
            steps = gcd(abs(dr), abs(dc))
            for s in range(1, steps):
                r = int(round(r1 + s * dr / steps))
                c = int(round(c1 + s * dc / steps))
                if orig_grid[r][c] == 0:
                    result[r][c] = 5

        # Horizontal copy - only if target is empty in original
        if cp2[0] >= 0 and cp2[1] >= 0 and cp2[1] < width:
            if orig_grid[cr][cp2[1]] == 0:
                result[cp2[0]][cp2[1]] = cval

                for c_col in range(min(cc, cp2[1]) + 1, max(cc, cp2[1])):
                    if orig_grid[cr][c_col] == 0:
                        result[cr][c_col] = 5

        # Original: even stays same, odd becomes 5
        if cval % 2 == 1:
            result[cr][cc] = 5
        else:
            result[cr][cc] = cval

    return result

